"""Moving elements to left and right to pivot to make sure arr[pi] is at the right position
Input:
    - arr: array to be sorted
    - start: start position/index
    - end: end position/index
Return: pi"""
def partition(arr: Any, start: Any, end: Any) -> object {
    _pi = arr[end];
    _small = start - 1;
    for i in range(start, end) {
        if (arr[i] <= _pi) {
            _small = _small + 1;
            (arr[_small], arr[i]) = (arr[i], arr[_small]);
        }
    }
    _small = _small + 1;
    (arr[_small], arr[end]) = (arr[end], arr[_small]);
    return _small;
}

"""
    last :: [a] -> a

    Extract the last element of a list, which must be finite and non-empty.
    """
def last(xs: Any) -> object {
    return xs[-1];
}

"""Filter cases.

    :param case_ids: Parameter list for pytest.mark.parametrize.
    :param to_filter: List of parameters to filter from case_ids.
    :return: Filtered case_ids.
    """
def filter(case_ids: Any, to_filter: Any) -> object {
    return [
        `case
        for `case in case_ids
        if (`case not in to_filter)
    ];
}

